const MASCOT_EYES = 'clawd_background'
const KUBE_BLUE = '#326CE5'
const WORKSPACE_GREEN = '#7FB77E'
const AGENTS_BLUE = '#7AA2F7'
const TOOLKIT_PURPLE = '#BB9AF7'
const TOOLKIT_MS = 60_000
const NO_ARGS = 'No arguments'
const CANCEL = 'Cancel'
// Secondary text that carries something to read: faint text falls under a
// readable contrast on most terminals, the theme's inactive grey does not.
const QUIET = 'inactive'
const TRACK = 'subtle'
const METER = '─'
