const isLiveLabel = (status: AgentStatusLabel) => status === 'running' || status === 'idle'
const isLive = (row: AgentRow) => isLiveLabel(row.status)

function statusLabel(status: AgentStatus): AgentStatusLabel {
  switch (status) {
    case 'idle':
    case 'completed':
    case 'failed':
    case 'killed':
      return status
    default:
      return 'running'
  }
}

export function modelLabel(model: string): string {
  const match = /^claude-([a-z]+)-(\d+)-(\d+)(?:-\d{8})?(\[1m\])?$/i.exec(model)
  if (match === null) return model
  const family = match[1] ?? ''
  const size = match[4] === undefined ? '' : ' · 1M'
  return `${family.charAt(0).toUpperCase()}${family.slice(1)} ${match[2]}.${match[3]}${size}`
}

export function tokens(count: number): string {
  if (count >= 1_000_000) return `${Number((count / 1_000_000).toFixed(1))}M`
  if (count >= 1_000) return `${Math.round(count / 1_000)}k`
  return String(count)
}

export function elapsed(ms: number): string {
  const seconds = Math.max(0, Math.round(ms / 1_000))
  return seconds < 60 ? `${seconds}s` : `${Math.floor(seconds / 60)}m ${seconds % 60}s`
}

export function span(ms: number): string {
  const minutes = Math.max(0, Math.floor(ms / 60_000))
  if (minutes < 60) return `${minutes}m`
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return `${hours}h ${String(minutes % 60).padStart(2, '0')}m`
  return `${Math.floor(hours / 24)}d ${hours % 24}h`
}

export function ago(ms: number): string {
  const minutes = Math.max(0, Math.floor(ms / 60_000))
  if (minutes < 1) return 'now'
  if (minutes < 60) return `${minutes}m`
  const hours = Math.floor(minutes / 60)
  return hours < 24 ? `${hours}h` : `${Math.floor(hours / 24)}d`
}

export type GitStatus = Pick<
  GitState,
  'branch' | 'isDetached' | 'oid' | 'upstream' | 'ahead' | 'behind' | 'staged' | 'modified' | 'untracked' | 'conflicts' | 'stashes'
>

// Reads `git status --porcelain=v2 --branch --show-stash`: headers, then one
// line per path whose XY pair is the index's state and the work tree's.
export function parseGitStatus(stdout: string): GitStatus {
  const status: GitStatus = {
    branch: '',
    isDetached: false,
    oid: null,
    upstream: null,
    ahead: null,
    behind: null,
    staged: 0,
    modified: 0,
    untracked: 0,
    conflicts: 0,
    stashes: 0,
  }
  for (const line of stdout.split('\n')) {
    const [kind = '', field = '', ...rest] = line.split(' ')
    if (kind === '#') {
      const value = printable(rest.join(' '))
      if (field === 'branch.oid') status.oid = value === '(initial)' ? null : value
      if (field === 'branch.head') {
        status.isDetached = value === '(detached)'
        status.branch = status.isDetached ? 'detached' : value
      }
      if (field === 'branch.upstream') status.upstream = value
      if (field === 'branch.ab') {
        status.ahead = Math.abs(Number(rest[0] ?? 0))
        status.behind = Math.abs(Number(rest[1] ?? 0))
      }
      if (field === 'stash') status.stashes = Number(rest[0] ?? 0)
    } else if (kind === '1' || kind === '2') {
      if (field[0] !== '.') status.staged++
      if (field[1] !== '.') status.modified++
    } else if (kind === 'u') {
      status.conflicts++
    } else if (kind === '?') {
      status.untracked++
    }
  }
  return status
}

const OPERATION_MARKERS: ReadonlyArray<[string, GitOperation]> = [
  ['rebase-merge', 'rebase'],
  ['rebase-apply', 'rebase'],
  ['MERGE_HEAD', 'merge'],
  ['CHERRY_PICK_HEAD', 'cherry-pick'],
  ['REVERT_HEAD', 'revert'],
  ['BISECT_LOG', 'bisect'],
]

export function gitOperation(names: readonly string[]): GitOperation | null {
  const present = new Set(names)
  return OPERATION_MARKERS.find(([marker]) => present.has(marker))?.[1] ?? null
}

export function parseKube(stdout: string): KubeState | null {
  const [context = '', namespace = ''] = stdout.trim().split('\t')
  const name = printable(context)
  return name === '' ? null : { context: name, namespace: printable(namespace) || null }
}

function levelColor(percent: number): Color {
  if (percent >= 85) return 'error'
  if (percent >= 60) return 'warning'
  return ORANGE
}

function statusColor(status: AgentStatusLabel): Color {
  switch (status) {
    case 'completed':
      return 'success'
    case 'failed':
      return 'error'
    case 'killed':
      return 'inactive'
    case 'idle':
      return 'warning'
    default:
      return AGENTS_BLUE
  }
}

function statusIcon(row: AgentRow, at: number, isStill: boolean): string {
  switch (row.status) {
    case 'completed':
      return '✓'
    case 'failed':
      return '✗'
    case 'killed':
      return '■'
    case 'idle':
      return '◌'
    default:
      return isStill ? '●' : (SPINNER[Math.floor(at / 1_000) % SPINNER.length] ?? '●')
  }
}

export type ListItem = { marker: string; text: string; depth: number }

export type ReplyBlock =
  | { kind: 'heading'; level: number; text: string }
  | { kind: 'list'; isOrdered: boolean; items: ListItem[] }
  | { kind: 'code'; language: string; source: string }
  | { kind: 'quote'; lines: string[] }
  | { kind: 'rule' }
  | { kind: 'markdown'; text: string }

const FENCE = /^\s*(`{3,}|~{3,})\s*([\w+#.-]*)/
// The closing #s are cut by hand: a lazy capture before `\s*#*\s*$` backtracks
// for seconds on one long line of spaces.
const HEADING = /^(#{1,6})\s+([^]*)$/
const RULE = /^\s*([-*_])(\s*\1){2,}\s*$/
const LIST_ITEM = /^(\s*)([-*+]|\d+[.)])\s+(.*)$/
const QUOTE = /^\s*>\s?(.*)$/

function headingText(raw: string): string {
  let end = raw.trimEnd().length
  while (end > 0 && raw[end - 1] === '#') end--
  return raw.slice(0, end).trimEnd()
}

// Splits a reply into the blocks the HUD styles itself; paragraphs and tables
// stay markdown so the engine's renderer keeps inline formatting and tables.
export function parseReply(text: string): ReplyBlock[] {
  const lines = text.replace(/\r\n/g, '\n').split('\n')
  const blocks: ReplyBlock[] = []
  let prose: string[] = []
  const flush = () => {
    if (prose.some(line => line.trim() !== '')) blocks.push({ kind: 'markdown', text: prose.join('\n').trim() })
    prose = []
  }

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i] ?? ''
    const fence = FENCE.exec(line)
    if (fence !== null) {
      flush()
      const mark = fence[1] ?? '```'
      const body: string[] = []
      i++
      while (i < lines.length && !(lines[i] ?? '').trim().startsWith(mark)) body.push(lines[i++] ?? '')
      blocks.push({ kind: 'code', language: fence[2] ?? '', source: body.join('\n') })
      continue
    }
    const heading = HEADING.exec(line)
    if (heading !== null) {
      flush()
      blocks.push({ kind: 'heading', level: (heading[1] ?? '#').length, text: headingText(heading[2] ?? '') })
      continue
    }
    if (RULE.test(line)) {
      flush()
      blocks.push({ kind: 'rule' })
      continue
    }
    const item = LIST_ITEM.exec(line)
    if (item !== null) {
      flush()
      const isOrdered = /\d/.test(item[2] ?? '')
      const items: ListItem[] = []
      while (i < lines.length) {
        const current = lines[i] ?? ''
        const match = LIST_ITEM.exec(current)
        if (match !== null && /\d/.test(match[2] ?? '') === isOrdered) {
          items.push({ marker: match[2] ?? '-', text: match[3] ?? '', depth: Math.floor((match[1] ?? '').length / 2) })
        } else if (current.trim() !== '' && /^\s+/.test(current) && items.length > 0) {
          const last = items[items.length - 1]
          if (last !== undefined) last.text = `${last.text}\n${current.trim()}`
        } else if (current.trim() === '' && LIST_ITEM.test(lines[i + 1] ?? '')) {
          // a blank line between items keeps the list going
        } else {
          break
        }
        i++
      }
      i--
      blocks.push({ kind: 'list', isOrdered, items })
      continue
    }
    const quote = QUOTE.exec(line)
    if (quote !== null) {
      flush()
      const quoted: string[] = []
      while (i < lines.length && QUOTE.test(lines[i] ?? '')) quoted.push(QUOTE.exec(lines[i++] ?? '')?.[1] ?? '')
      i--
      blocks.push({ kind: 'quote', lines: quoted })
      continue
    }
    if (line.trim() === '') {
      flush()
      continue
    }
    prose.push(line)
  }
  flush()

  return blocks
}

export type GroupRow = {
  uuid: string
  isPrompt: boolean
  isAssistant: boolean
  blocks: ReadonlyArray<{ type: string; id?: unknown; name?: unknown }>
}

export type GroupTracker = {
  pending: Array<{ key: string; isText: boolean }>
  group: TurnGroupView | null
}

export type GroupChange = { members: string[]; view: TurnGroupView }

// Folds a turn's work into one group: prose a tool call follows, and the calls.
// Prose no call follows (the final answer) stays out, and so does everything up
// to a call that asks the person something, which also closes the group.
export function noteGroupRow(tracker: GroupTracker, row: GroupRow): GroupChange | null {
  if (row.isPrompt) {
    tracker.pending = []
    tracker.group = null
    return null
  }
  if (!row.isAssistant) return null

  const calls = row.blocks.filter(block => block.type === 'tool_use' && typeof block.id === 'string')
  const isText = row.blocks.some(block => block.type === 'text')
  const isProse = isText || row.blocks.some(block => block.type === 'thinking' || block.type === 'redacted_thinking')
  if (calls.length === 0) {
    if (isProse) tracker.pending.push({ key: row.uuid, isText })
    return null
  }
  if (calls.some(call => ASKING_TOOLS.has(String(call.name)))) {
    tracker.pending = []
    tracker.group = null
    return null
  }

  const prose = isProse ? [...tracker.pending, { key: row.uuid, isText }] : tracker.pending
  const members = [...prose.map(part => part.key), ...calls.map(call => String(call.id))]
  // The head draws the group's summary line, so it must be a row the transcript
  // draws: thinking rows are hidden there, so a text row or the first call.
  const head = prose.find(part => part.isText)?.key ?? String(calls[0]?.id ?? row.uuid)
  const current = tracker.group ?? { head, texts: 0, tools: {}, last: null, isActive: true }
  const tools = { ...current.tools }
  for (const call of calls) {
    const name = printable(String(call.name)).replace(/^mcp__[^_]+__/, '')
    tools[name] = (tools[name] ?? 0) + 1
  }
  const view: TurnGroupView = {
    head: current.head,
    texts: current.texts + prose.filter(part => part.isText).length,
    tools,
    last: printable(String(calls.at(-1)?.name ?? '')).replace(/^mcp__[^_]+__/, '') || null,
    isActive: true,
  }
  tracker.pending = []
  tracker.group = view

  return { members, view }
}

export function groupSummary(view: TurnGroupView): string {
  const tools = Object.entries(view.tools).sort((a, b) => b[1] - a[1])
  const calls = tools.reduce((total, [, count]) => total + count, 0)
  const counts = [
    view.texts > 0 ? `${view.texts} text${view.texts === 1 ? '' : 's'}` : null,
    `${calls} tool${calls === 1 ? '' : 's'}`,
  ].filter(part => part !== null)
  const detail = tools.slice(0, 4).map(([name, count]) => `${name} ${count}`).join(' · ')
  const lead = view.isActive ? `working${view.last !== null ? ` (${view.last})` : ''} · ` : ''

  return `${lead}${counts.join(' · ')}${detail === '' ? '' : ` — ${detail}`}`
}

export type GroupDrawing = 'engine' | 'hidden' | 'summary' | 'expanded-head'

// A call's result and progress rows carry its id but never head the group: the
// call's own row does, and a screen reader's drawing shows the result apart.
export function groupDrawing(
  head: string | null,
  keys: readonly string[],
  isOpen: boolean,
  isShowingAll: boolean,
  canHead = true,
): GroupDrawing {
  if (isShowingAll || head === null) return 'engine'
  const isHead = canHead && keys.includes(head)
  if (isOpen) return isHead ? 'expanded-head' : 'engine'
  return isHead ? 'summary' : 'hidden'
}

// Text from outside the session (a kubeconfig, git, the model) is drawn as is,
// so control characters that could carry terminal escape sequences are dropped.
export function printable(text: string): string {
  return text.replace(/[\u0000-\u001f\u007f-\u009f]/g, '')
}

function printableLines(text: string): string {
  return text.replace(/[\u0000-\u0008\u000b-\u001f\u007f-\u009f]/g, '')
}

export function clip(text: string, width: number): string {
  if (text.length <= width) return text
  return width <= 1 ? text.slice(0, Math.max(0, width)) : `${text.slice(0, width - 1)}…`
}

const SUMMARY_KEYS = ['file_path', 'path', 'pattern', 'command', 'url', 'query', 'skill', 'description', 'prompt']

export function toolSummary(input: Record<string, unknown>): string {
  for (const key of SUMMARY_KEYS) {
    const value = input[key]
    if (typeof value === 'string' && value.trim() !== '') return clip(printable(value.replace(/\s+/g, ' ').trim()), 200)
  }
  return ''
}

// An agent's conversation as the viewer draws it: tool results are read off the
// calls they answer, and injected reminders are not the agent's prompt.
export function agentLogEntries(messages: readonly SessionMessage[]): AgentLogEntry[] {
  const entries: AgentLogEntry[] = []
  for (const message of messages) {
    if (message.role === 'user') {
      if ((message.toolResults?.length ?? 0) > 0) continue
      const text = printableLines(message.text.replace(/<system-reminder>[\s\S]*?<\/system-reminder>/g, '')).trim()
      if (text !== '') entries.push({ kind: 'prompt', text })
      continue
    }
    const text = printableLines(message.text).trim()
    if (text !== '') entries.push({ kind: 'reply', text })
    for (const use of message.toolUses) {
      const outcome: AgentToolOutcome =
        use.isError === true ? 'error' : use.text === undefined && use.result === undefined ? 'pending' : 'ok'
      entries.push({
        kind: 'tool',
        name: printable(use.tool).replace(/^mcp__[^_]+__/, ''),
        summary: toolSummary(use.input),
        outcome,
      })
    }
  }
  return entries.slice(-MAX_LOG_ENTRIES)
}

function cwdLabel(hud: HudInfo): string {
  if (hud.home !== null && hud.cwd === hud.home) return '~'
  return printable(hud.cwd.split('/').filter(part => part !== '').at(-1) ?? hud.cwd)
}

async function attempt<T>(work: () => Promise<T>, fallback: T): Promise<T> {
  try {
    return await work()
  } catch {
    return fallback
  }
}

async function storeEffort($: EngineInterface, value: string): Promise<void> {
  if ((await read($, effort)) === value) return
  await update($, effort, () => value)
}

// No optional locks: a background poll must not take the index lock from the
// person's own git commands. No fsmonitor: its hook is a command a config names.
const GIT = ['git', '--no-optional-locks', '-c', 'core.fsmonitor=false'] as const

// A filter the repo's own config names runs on `git status`, so each one is
// emptied for the HUD's call; a name `-c` cannot spell leaves git out instead.
export function filterOverrides(listing: string): string[] | null {
  const fields = listing.split('\0')
  const names = new Set<string>()
  for (let i = 0; i + 1 < fields.length; i += 2) {
    if (fields[i] !== 'local' && fields[i] !== 'worktree') continue
    const name = /^filter\.([^]*)\.[^.]*$/.exec(fields[i + 1] ?? '')?.[1]
    if (name === undefined) continue
    if (/[=\n]/.test(name)) return null
    names.add(name)
  }
  return [...names].flatMap(name => ['-c', `filter.${name}.clean=`, '-c', `filter.${name}.process=`])
}

let repoCache: { cwd: string; root: string; gitDir: string; isWorktree: boolean } | undefined
let commitCache: { oid: string; commit: GitCommit | null } | undefined

async function gitRepo($: EngineInterface, cwd: string): Promise<typeof repoCache> {
  if (repoCache?.cwd === cwd) return repoCache
  const run = await $.process.run(
    [...GIT, 'rev-parse', '--path-format=absolute', '--show-toplevel', '--git-dir', '--git-common-dir'],
    { timeoutMs: 2_000 },
  )
  if (run.exitCode !== 0) return undefined
  const [root = '', gitDir = '', commonDir = ''] = run.stdout.split('\n')
  repoCache = { cwd, root, gitDir, isWorktree: gitDir !== commonDir }
  return repoCache
}

async function lastCommit($: EngineInterface, oid: string | null): Promise<GitCommit | null> {
  if (oid === null) return null
  if (commitCache?.oid === oid) return commitCache.commit
  const run = await $.process.run([...GIT, 'log', '-1', '--no-show-signature', '--format=%h%x1f%ct%x1f%s'], { timeoutMs: 2_000 })
  const [hash = '', at = '', subject = ''] = run.exitCode === 0 ? run.stdout.trim().split('\x1f') : []
  const commit = hash === '' ? null : { hash: printable(hash), subject: printable(subject), at: Number(at) * 1_000 }
  commitCache = { oid, commit }
  return commit
}

// A rebase, merge or pick in progress leaves its marker in the git dir, so a
// listing tells without a process; a rebase's step is two numbers beside it.
async function gitProgress($: EngineInterface, gitDir: string): Promise<Pick<GitState, 'operation' | 'step'>> {
  const names = (await attempt(() => $.fs.list(gitDir), [])).map(entry => entry.name)
  const operation = gitOperation(names)
  if (operation !== 'rebase') return { operation, step: null }
  const isMerge = names.includes('rebase-merge')
  const dir = `${gitDir}/${isMerge ? 'rebase-merge' : 'rebase-apply'}`
  const read = (name: string) => attempt(async () => (await $.fs.read(`${dir}/${name}`)).trim(), '')
  const [done, total] = await Promise.all([read(isMerge ? 'msgnum' : 'next'), read(isMerge ? 'end' : 'last')])
  return { operation, step: /^\d+$/.test(done) && /^\d+$/.test(total) ? `${done}/${total}` : null }
}

async function gitState($: EngineInterface): Promise<GitState | null> {
  const filters = await $.process.run([...GIT, 'config', '--show-scope', '-z', '--name-only', '--get-regexp', '^filter\\.'], {
    timeoutMs: 2_000,
  })
  const overrides =
    filters.exitCode === 1 ? [] : filters.exitCode === 0 && !filters.isStdoutTruncated ? filterOverrides(filters.stdout) : null
  if (overrides === null) return null
  // A submodule's own status would run its filters, which are not emptied here.
  const run = await $.process.run(
    [...GIT, ...overrides, 'status', '--porcelain=v2', '--branch', '--show-stash', '--ignore-submodules=dirty'],
    { timeoutMs: 2_000 },
  )
  if (run.exitCode !== 0) return null
  const status = parseGitStatus(run.stdout)
  const cwd = await $.session.cwd()
  const repo = await gitRepo($, cwd)
  const [progress, commit] = await Promise.all([
    repo === undefined ? { operation: null, step: null } : gitProgress($, repo.gitDir),
    lastCommit($, status.oid),
  ])
  const root = repo?.root ?? cwd
  return {
    ...status,
    ...progress,
    lastCommit: commit,
    repo: printable(root.split('/').filter(part => part !== '').at(-1) ?? root),
    subdir: repo !== undefined && cwd.startsWith(`${root}/`) ? printable(cwd.slice(root.length + 1)) : null,
    isWorktree: repo?.isWorktree ?? false,
  }
}

async function kubeState($: EngineInterface): Promise<KubeState | null> {
  const run = await $.process.run(
    ['kubectl', 'config', 'view', '--minify', '-o', 'jsonpath={.current-context}{"\\t"}{..namespace}'],
    { timeoutMs: 2_000 },
  )
  return run.exitCode === 0 ? parseKube(run.stdout) : null
}

// Only a line that is a title record: the same key inside a tool's output is not.
const TITLE_PATTERN = '^\\{"type":"(custom-title","customTitle|ai-title","aiTitle)":"([^"\\\\]|\\\\.)*"'
let transcript: { id: string; path: string } | undefined
// The title last read, keyed by the transcript's size and mtime: re-read only once the file changed.
let titleCache: { id: string; stamp: string; title: string | null } | undefined

// The title a /rename set wins over the one Claude Code generated; both are the
// latest of their kind in the transcript lines `grep` hands back.
export function pickSessionTitle(lines: readonly string[]): string | null {
  let custom: string | null = null
  let generated: string | null = null
  for (const line of lines) {
    try {
      const entry = JSON.parse(`${line}}`) as { customTitle?: unknown; aiTitle?: unknown }
      if (typeof entry.customTitle === 'string') custom = entry.customTitle
      if (typeof entry.aiTitle === 'string') generated = entry.aiTitle
    } catch {
      // a line grep cut mid-escape is skipped
    }
  }
  const title = printable(custom ?? generated ?? '').trim()
  return title === '' ? null : title
}

export function isTitleFresh(
  cache: { id: string; stamp: string } | undefined,
  id: string,
  stamp: string,
): boolean {
  return cache !== undefined && cache.id === id && cache.stamp === stamp
}

// No API carries the session's name, so it is read off the transcript. The file
// outgrows $.fs.read's limit, so grep returns only the title entries.
async function sessionTitle($: EngineInterface, configDir: string): Promise<string | null> {
  const id = await $.session.id()
  if (!/^[0-9a-f-]{36}$/i.test(id)) return null
  if (transcript?.id !== id) {
    const found = await $.process.run(
      ['find', `${configDir}/projects`, '-maxdepth', '2', '-name', `${id}.jsonl`, '-print', '-quit'],
      { timeoutMs: 3_000 },
    )
    const path = found.exitCode === 0 ? found.stdout.trim() : ''
    if (path === '') return null
    transcript = { id, path }
  }
  const stat = await $.fs.stat(transcript.path)
  const stamp = `${stat.size}:${stat.mtimeMs}`
  if (titleCache !== undefined && isTitleFresh(titleCache, id, stamp)) return titleCache.title
  const run = await $.process.run(['grep', '-a', '-o', '-E', TITLE_PATTERN, transcript.path], { timeoutMs: 3_000 })
  const title = run.exitCode === 0 ? pickSessionTitle(run.stdout.split('\n').filter(line => line !== '')) : null
  titleCache = { id, stamp, title }
  return title
}

// Mirrors ~/.claude/hooks/caveman-statusline.sh, which the HUD replaces; the
// flag text is reduced to [a-z0-9-] so nothing from the file reaches the terminal raw.
async function cavemanBadge($: EngineInterface, configDir: string): Promise<string | null> {
  const raw = await $.fs.read(`${configDir}/.caveman-active`)
  const mode = raw.slice(0, 64).toLowerCase().replace(/[^a-z0-9-]/g, '')
  if (!CAVEMAN_MODES.has(mode)) return null
  const badge = mode === 'full' ? '[CAVEMAN]' : `[CAVEMAN:${mode.toUpperCase()}]`
  const savings = await attempt(
    async () => (await $.fs.read(`${configDir}/.caveman-statusline-suffix`)).slice(0, 64).replace(/[\u0000-\u001f\u007f]/g, '').trim(),
    '',
  )
  return savings === '' ? badge : `${badge} ${savings}`
}

async function configDirOf($: EngineInterface, home: string | undefined): Promise<string | undefined> {
  const explicit = await attempt(() => $.env.get('CLAUDE_CONFIG_DIR'), undefined)
  return explicit ?? (home === undefined ? undefined : `${home}/.claude`)
}

// /effort saves the level under the model it was set for, and the plain
// effortLevel is what a model with no entry of its own runs at.
export function settingsEffort(settings: Readonly<Record<string, unknown>>, model: string): string | null {
  const field = (value: unknown, key: string): unknown =>
    typeof value === 'object' && value !== null ? (value as Record<string, unknown>)[key] : undefined
  const base = model.replace(/\[1m\]$/i, '').replace(/-\d{8}$/, '')
  const level = field(field(settings['modelSettings'], base), 'effortLevel') ?? settings['effortLevel']
  return typeof level === 'string' && level !== '' ? printable(level) : null
}

const EFFORT_LEVELS = new Set(['low', 'medium', 'high', 'xhigh', 'max'])

// /effort's output, kept as a command row whether typed or picked, names the
// level it set: the only trace of one set for this session alone, which the
// settings never see.
export function effortSet(text: string): string | null {
  const level = /<local-command-stdout>Set effort level to ([a-z]+)\b/.exec(text)?.[1]
  return level !== undefined && EFFORT_LEVELS.has(level) ? level : null
}

const ON_WORDS = ['1', 'true', 'yes', 'on']
const OFF_WORDS = ['0', 'false', 'no', 'off']

// Claude Code's own switches, in its order: --ax-screen-reader, which no plugin
// can read, then CLAUDE_AX_SCREEN_READER, then the axScreenReader setting.
export function accessMode(settings: Readonly<Record<string, unknown>>, screenReaderEnv: string | undefined): AccessMode {
  const word = screenReaderEnv?.trim().toLowerCase() ?? ''
  return {
    isScreenReader: ON_WORDS.includes(word) || (!OFF_WORDS.includes(word) && settings['axScreenReader'] === true),
    isReducedMotion: settings['prefersReducedMotion'] === true,
  }
}

type LiveInfo = Omit<HudInfo, 'git' | 'kube' | 'sessionTitle' | 'fetchedAt'>
type WorkspaceInfo = Pick<HudInfo, 'git' | 'kube' | 'sessionTitle'>

const NO_INFO: HudInfo = {
  version: '',
  model: '',
  cwd: '',
  home: null,
  git: null,
  kube: null,
  contextPercent: null,
  contextTokens: null,
  contextWindow: 0,
  rateLimits: [],
  costUsd: null,
  prompts: null,
  sessionStartedAt: null,
  fetchedAt: 0,
  effortSetting: null,
  caveman: null,
  sessionTitle: null,
}

// What the session reports in process, no child spawned: cheap enough to poll each second.
async function collectLive($: EngineInterface): Promise<LiveInfo & { access: AccessMode }> {
  const home = await attempt(() => $.env.get('HOME'), undefined)
  const configDir = await configDirOf($, home)
  const [version, model, cwd, usage, prompts, settings, caveman, screenReader] = await Promise.all([
    attempt(async () => (await $.session.version()).version, ''),
    attempt(() => $.session.model(), ''),
    attempt(() => $.session.cwd(), ''),
    attempt(() => $.session.usage(), undefined),
    attempt(() => $.session.turns(), null),
    attempt(() => $.settings.read(), {}),
    configDir === undefined ? Promise.resolve(null) : attempt(() => cavemanBadge($, configDir), null),
    attempt(() => $.env.get('CLAUDE_AX_SCREEN_READER'), undefined),
  ])
  const rateLimits: RateLimitGauge[] = (usage?.rateLimits ?? []).map(limit => {
    const resetsAt = limit.resetsAt === undefined ? NaN : Date.parse(limit.resetsAt)
    return {
      label: LIMIT_LABELS[limit.kind] ?? limit.kind,
      percent: limit.percentUsed,
      resetsAt: Number.isNaN(resetsAt) ? null : resetsAt,
    }
  })

  return {
    version,
    model,
    cwd,
    home: home ?? null,
    contextPercent: usage?.context.percent ?? null,
    contextTokens: usage?.context.tokens ?? null,
    contextWindow: usage?.context.window ?? 0,
    rateLimits,
    costUsd: usage?.cost?.usd ?? null,
    prompts,
    sessionStartedAt: usage?.startedAt ?? null,
    effortSetting: settingsEffort(settings, model),
    caveman,
    access: accessMode(settings, screenReader),
  }
}

async function collectWorkspace($: EngineInterface): Promise<WorkspaceInfo> {
  const configDir = await configDirOf($, await attempt(() => $.env.get('HOME'), undefined))
  const [git, kube, title] = await Promise.all([
    attempt(() => gitState($), null),
    attempt(() => kubeState($), null),
    configDir === undefined ? Promise.resolve(null) : attempt(() => sessionTitle($, configDir), null),
  ])
  return { git, kube, sessionTitle: title }
}

type Refresh = 'live' | 'access' | 'workspace' | 'toolkit'

let passes = 0
const landed: Record<Refresh, number> = { live: 0, access: 0, workspace: 0, toolkit: 0 }

// Refreshes overlap (the timers, a turn's end, a command), so a pass lands only
// if no later one has: a slow pass never writes an older snapshot over a newer
// one, and a pass that never settles holds nothing up. Called inside update's
// function, so a write retried after a newer one landed is dropped too.
function lands(refresh: Refresh, pass: number): boolean {
  if (pass < landed[refresh]) return false
  landed[refresh] = pass
  return true
}

// Durations are drawn against fetchedAt, so it moves on each minute and as a
// limit's reset passes, and not on every poll.
function clockMark(at: number, limits: readonly RateLimitGauge[]): string {
  return `${Math.floor(at / 60_000)}:${limits.filter(limit => limit.resetsAt !== null && limit.resetsAt <= at).length}`
}

async function refreshLive($: EngineInterface): Promise<void> {
  const pass = ++passes
  const { access: mode, ...fresh } = await collectLive($)
  const at = await $.clock.now()
  const current = await read($, info)
  if (pass < landed.live) return
  const isSame =
    current !== null &&
    JSON.stringify({ ...current, ...fresh }) === JSON.stringify(current) &&
    clockMark(current.fetchedAt, current.rateLimits) === clockMark(at, fresh.rateLimits)
  if (!isSame) await update($, info, value => (lands('live', pass) ? { ...(value ?? NO_INFO), ...fresh, fetchedAt: at } : value))
  // A level the settings take on (an /effort, a /model) is newer than the one
  // the last turn reported, so it replaces it until the next turn reports again.
  if (pass === landed.live && current !== null && fresh.effortSetting !== null && fresh.effortSetting !== current.effortSetting) {
    await storeEffort($, fresh.effortSetting)
  }
  if (pass >= landed.access && JSON.stringify(await read($, access)) !== JSON.stringify(mode)) {
    await update($, access, value => (lands('access', pass) ? mode : value))
  }
}

async function refreshWorkspace($: EngineInterface): Promise<void> {
  const pass = ++passes
  const fresh = await collectWorkspace($)
  const at = await $.clock.now()
  const current = await read($, info)
  if (pass < landed.workspace) return
  if (current !== null && JSON.stringify({ ...current, ...fresh }) === JSON.stringify(current)) return
  await update($, info, value =>
    lands('workspace', pass) ? { ...(value ?? { ...NO_INFO, fetchedAt: at }), ...fresh } : value,
  )
}

// Re-reads the session title alone, for the moment a /rename has just written it.
async function refreshTitle($: EngineInterface): Promise<void> {
  const configDir = await configDirOf($, await attempt(() => $.env.get('HOME'), undefined))
  if (configDir === undefined) return
  const title = await attempt(() => sessionTitle($, configDir), null)
  const current = await read($, info)
  if (current === null || current.sessionTitle === title) return
  await update($, info, value => (value === null ? value : { ...value, sessionTitle: title }))
}

// Reads `name` and `description` off a definition's front matter: plain,
// quoted or block (`>`, `|`) values, which is all agent and skill files use.
export function parseFrontmatter(text: string): ToolDefinition | null {
  const lines = text.replace(/\r\n/g, '\n').split('\n')
  if (lines[0]?.trim() !== '---') return null
  const fields: Record<string, string> = {}
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i] ?? ''
    if (line.trim() === '---') break
    const match = /^([A-Za-z_][\w-]*):\s*(.*)$/.exec(line)
    if (match === null) continue
    let value = (match[2] ?? '').trim()
    if (/^[>|][+-]?$/.test(value)) {
      const block: string[] = []
      while (i + 1 < lines.length && /^\s+\S/.test(lines[i + 1] ?? '')) block.push((lines[++i] ?? '').trim())
      value = block.join(' ')
    }
    fields[match[1] ?? ''] = value.replace(/^(['"])(.*)\1$/, '$2')
  }
  const name = printable(fields['name'] ?? '').trim()
  return name === '' ? null : { name, description: printable(fields['description'] ?? '').trim() }
}

// Claude Code's own rule for agent and skill names; anything else in a repo's
// definition is not offered, so the prompt box and /name carry no surprises.
const DEFINITION_NAME = /^[a-z0-9][a-z0-9-]{0,63}$/
const MAX_DEFINITIONS = 100
const MAX_DEFINITION_BYTES = 64 * 1024

// A repo's definitions may be links: only a regular file of a definition's size
// is read, never a device or a pipe one points to.
async function readDefinition($: EngineInterface, path: string): Promise<ToolDefinition | null> {
  const stat = await $.fs.stat(path)
  if (stat.kind !== 'file' || stat.size > MAX_DEFINITION_BYTES) return null
  const definition = parseFrontmatter(await $.fs.read(path))
  return definition !== null && DEFINITION_NAME.test(definition.name) ? definition : null
}

async function readDefinitions($: EngineInterface, dir: string, kind: 'agents' | 'skills'): Promise<ToolDefinition[]> {
  const entries = await attempt(() => $.fs.list(dir), [])
  const paths =
    kind === 'agents'
      ? entries.filter(entry => entry.kind === 'file' && entry.name.endsWith('.md')).map(entry => `${dir}/${entry.name}`)
      : entries.filter(entry => entry.kind !== 'file' && !entry.name.startsWith('.')).map(entry => `${dir}/${entry.name}/SKILL.md`)
  const found = await Promise.all(paths.slice(0, MAX_DEFINITIONS).map(path => attempt(() => readDefinition($, path), null)))
  return found.filter(definition => definition !== null).sort((a, b) => a.name.localeCompare(b.name))
}

// The repo's own definitions first; the person's own follow, less any the repo
// redefines under the same name.
async function collectToolkit($: EngineInterface): Promise<ToolkitGroup[]> {
  const configDir = await configDirOf($, await attempt(() => $.env.get('HOME'), undefined))
  const root = await attempt(() => $.session.root(), '')
  // A skill named like a built-in or a plugin's command would run that command
  // under the skill's description, so it is not offered.
  const taken = new Set((await attempt(() => $.command.list(), [])).filter(one => one.source !== 'user').map(one => one.name))
  const readSkills = async (dir: string) => (await readDefinitions($, dir, 'skills')).filter(one => !taken.has(one.name))
  const groups: ToolkitGroup[] = []
  if (root !== '' && `${root}/.claude` !== configDir) {
    const [agentDefs, skillDefs] = await Promise.all([
      readDefinitions($, `${root}/.claude/agents`, 'agents'),
      readSkills(`${root}/.claude/skills`),
    ])
    const label = printable(root.split('/').filter(part => part !== '').at(-1) ?? root)
    if (agentDefs.length + skillDefs.length > 0) groups.push({ origin: 'repo', label, agents: agentDefs, skills: skillDefs })
  }
  if (configDir !== undefined) {
    const repo = groups[0]
    const [agentDefs, skillDefs] = await Promise.all([
      readDefinitions($, `${configDir}/agents`, 'agents'),
      readSkills(`${configDir}/skills`),
    ])
    const agentsLeft = agentDefs.filter(one => !repo?.agents.some(other => other.name === one.name))
    const skillsLeft = skillDefs.filter(one => !repo?.skills.some(other => other.name === one.name))
    if (agentsLeft.length + skillsLeft.length > 0) groups.push({ origin: 'user', label: 'you', agents: agentsLeft, skills: skillsLeft })
  }
  return groups
}

async function refreshToolkit($: EngineInterface): Promise<void> {
  const pass = ++passes
  const fresh = await collectToolkit($)
  if (pass < landed.toolkit || JSON.stringify(await read($, toolkit)) === JSON.stringify(fresh)) return
  await update($, toolkit, value => (lands('toolkit', pass) ? fresh : value))
}

// Claude launches the agent: the request is left in the prompt box for the
// person to finish with the task, under anything already typed there.
async function askForAgent($: EngineInterface, name: string): Promise<void> {
  const request = `Use the ${name} agent to `
  const box = await $.prompt.read()
  await $.prompt.fill(box.text.trim() === '' ? { text: request } : { text: `\n${request}`, mode: 'append' })
}

export function skillArgs(answer: string): string | null {
  if (answer === CANCEL) return null
  return answer === NO_ARGS ? '' : answer.trim()
}

async function runSkill($: EngineInterface, name: string): Promise<void> {
  const answer = await attempt(
    () => $.ui.ask(`Arguments for /${name}?`, { options: [NO_ARGS, CANCEL], header: 'Skill' }),
    CANCEL,
  )
  const args = skillArgs(answer)
  if (args === null) return
  try {
    await $.command.run({ command: name, args })
  } catch {
    $.ui.toast(`/${name} could not be run`)
  }
}

// A drawing that finds no figures yet asks for them from outside the draw.
function queueRefresh($: EngineInterface): void {
  if (isRefreshQueued) return
  isRefreshQueued = true
  $.clock.after(1, () => {
    void refreshLive($)
    void refreshWorkspace($)
    void refreshToolkit($)
  })
}

function noteSession($: EngineInterface, e: ClassicSessionFields): void {
  if (e.agent_id !== undefined) return
  if (e.effort?.level) void storeEffort($, e.effort.level)
}

async function openPane($: EngineInterface, isAsked: boolean): Promise<void> {
  const columns = (await read($, viewing)) === null ? PANE_COLUMNS : VIEWER_COLUMNS
  const opened = await $.ui.open({ id: PANE, title: 'HUD', columns })
  $.ui.invalidate('ui.render')
  if (!opened.isPlaced && !isAsked && !paneHinted) {
    paneHinted = true
    $.ui.toast('HUD: widen the terminal or run /hud to dock it on the right')
  }
}

async function loadAgentLog($: EngineInterface): Promise<void> {
  const agentId = await read($, viewing)
  if (agentId === null) return
  const found = await attempt(() => $.session.messages({ agentId }), { deny: 'unreadable' })
  if ((await read($, viewing)) !== agentId) return
  const current = await read($, agentLog)
  if (!Array.isArray(found) && current?.agentId === agentId && current.entries.length > 0) return
  const fresh: AgentLogView = Array.isArray(found)
    ? { agentId, entries: agentLogEntries(found), isDenied: false }
    : { agentId, entries: [], isDenied: true }
  if (JSON.stringify(current) === JSON.stringify(fresh)) return
  await update($, agentLog, () => fresh)
}

// A refresh asked for while one runs is folded into one more pass after it, so
// an agent's last turn is never dropped behind a poll that read it a moment early.
async function refreshAgentLog($: EngineInterface): Promise<void> {
  if (isLogLoading) {
    isLogStale = true
    return
  }
  isLogLoading = true
  try {
    do {
      isLogStale = false
      await loadAgentLog($)
    } while (isLogStale)
  } finally {
    isLogLoading = false
  }
}

async function showAgent($: EngineInterface, agentId: string | null): Promise<void> {
  await update($, viewing, () => agentId)
  await update($, agentLog, () => null)
  await openPane($, true)
  if (agentId === null) return
  await refreshAgentLog($)
  await attempt(() => $.ui.scroll({ to: 'end', in: PANE }), undefined)
}

async function isHudInPane($: EngineInterface): Promise<boolean> {
  const panes = await attempt(() => $.ui.panes(), [])
  return panes.some(pane => pane.id === PANE && pane.isPlaced && pane.isShown)
}

async function finish(
  $: EngineInterface,
  matches: (row: AgentRow) => boolean,
  status: AgentStatusLabel,
  totals?: { tools?: number; tokens?: number },
): Promise<void> {
  const at = await $.clock.now()
  await update($, agents, list =>
    list.map(row =>
      matches(row) && isLive(row)
        ? { ...row, status, endedAt: at, tools: totals?.tools ?? row.tools, tokens: totals?.tokens ?? row.tokens }
        : row,
    ),
  )
}

async function countTool($: EngineInterface, agentId: string, tool: string): Promise<void> {
  const list = await read($, agents)
  if (!list.some(row => row.id === agentId && isLive(row))) return
  await update($, agents, rows =>
    rows.map(row => (row.id === agentId ? { ...row, tools: row.tools + 1, lastTool: printable(tool) } : row)),
  )
}

async function pollAgents($: EngineInterface): Promise<void> {
  const at = await $.clock.now()
  const rows = await read($, agents)
  if (!rows.some(isLive)) {
    poller?.cancel()
    poller = undefined
    return
  }
  await update($, now, () => at)
  const listed = new Map((await $.agent.list()).map(agent => [agent.id, agent.status]))
  await update($, agents, list =>
    list.map((row): AgentRow => {
      if (!isLive(row)) return row
      const status = listed.get(row.id)
      if (status === undefined) {
        return at - row.startedAt > GRACE_MS ? { ...row, status: 'completed', endedAt: at } : row
      }
      const label = statusLabel(status)
      if (label === row.status) return row
      return isLiveLabel(label) ? { ...row, status: label } : { ...row, status: label, endedAt: at }
    }),
  )
  const shown = await read($, viewing)
  if (shown !== null && rows.some(row => row.id === shown && isLive(row))) void refreshAgentLog($)
}

function ensurePoller($: EngineInterface): void {
  if (poller !== undefined) return
  poller = $.clock.every(POLL_MS, () => void pollAgents($))
}

// A secondary control, drawn from a Text child so it rests in a theme colour:
// the Button's own dimColor is faint text. Its hover needs a keyed Box above it.
function quietButton(
  $: EngineInterface,
  e: ResolveInput,
  key: string,
  text: string,
  onPress: () => unknown,
  color: Color = QUIET,
): RenderElement {
  const { Button, Text } = $.ui.resolve(e)

  return (
    <Button key={key} label={text} plain hover={{ inverse: false }} onPress={() => void onPress()}>
      <Text color={color} hover={{ color: 'text', bold: true }}>{text}</Text>
    </Button>
  )
}

async function drawGrouped(
  $: EngineInterface,
  e: TranscriptInput,
  keys: readonly string[],
  draw: () => Promise<RenderElement>,
  canHead = true,
): Promise<RenderElement> {
  let found: string | null = null
  for (const key of keys) {
    found = await read($, memberOf(groupOf, { requestId: key }))
    if (found !== null) break
  }
  const head = found
  const [view, isOpen, isShowingAll] = await Promise.all([
    head === null ? Promise.resolve(null) : read($, memberOf(turnGroup, { requestId: head })),
    head === null ? Promise.resolve(false) : read($, memberOf(groupOpen, { requestId: head })),
    read($, showThoughts),
  ])
  const drawing = groupDrawing(view === null ? null : head, keys, isOpen, isShowingAll, canHead)
  if (drawing === 'engine' || head === null || view === null) return draw()

  const { Box } = $.ui.resolve(e)
  if (drawing === 'hidden') return <Box />
  if (drawing === 'expanded-head') {
    const drawn = await draw()
    return (
      <Box flexDirection="column">
        <Box key="group-row">
          {quietButton($, e, 'group', `▾ hide · ${groupSummary(view)}`, () => update($, memberOf(groupOpen, { requestId: head }), () => false))}
        </Box>
        {drawn}
      </Box>
    )
  }

  return (
    <Box key="group-row" paddingLeft={2}>
      {quietButton($, e, 'group', `▸ ${groupSummary(view)}`, () => update($, memberOf(groupOpen, { requestId: head }), () => true))}
    </Box>
  )
}

// Plain, for a screen reader: no glyph that is only decoration, and no rule,
// which it reads out character by character.
function replyBlock($: EngineInterface, e: ResolveInput, block: ReplyBlock, columns: number, isPlain: boolean): RenderElement {
  const { Box, Code, Markdown, Text } = $.ui.resolve(e)
  const plain = (text: string) => text.replace(/\*\*|__|`/g, '')
  const rule = '─'.repeat(Math.max(1, columns))

  switch (block.kind) {
    case 'heading':
      return block.level <= 2 && !isPlain ? (
        <Box flexDirection="column">
          <Text color={ORANGE} bold>{`◆ ${plain(block.text)}`}</Text>
          <Text color={ORANGE} dimColor wrap="truncate-end">{rule}</Text>
        </Box>
      ) : (
        <Text color={block.level <= 3 ? ORANGE : 'text'} bold>{plain(block.text)}</Text>
      )
    case 'list': {
      let ordinal = 0
      return (
        <Box flexDirection="column">
          {block.items.map(item => {
            ordinal = item.depth === 0 ? ordinal + 1 : ordinal
            const marker = block.isOrdered && item.depth === 0 ? String(ordinal) : item.depth === 0 ? '•' : '◦'
            return (
              <Box paddingLeft={item.depth * 2}>
                <Box flexShrink={0} width={block.isOrdered ? 4 : 3}>
                  <Text color={ORANGE} bold>{marker}</Text>
                </Box>
                <Box flexShrink={1} flexGrow={1}>
                  <Markdown text={item.text} />
                </Box>
              </Box>
            )
          })}
        </Box>
      )
    }
    case 'code':
      return (
        <Box flexDirection="column" backgroundColor={CODE_CARD} paddingX={1}>
          {block.language !== '' ? <Text color={ORANGE}>{block.language}</Text> : null}
          {block.language !== '' ? (
            <Code source={block.source} language={block.language} wrap="wrap" />
          ) : (
            <Code source={block.source} wrap="wrap" />
          )}
        </Box>
      )
    case 'quote':
      return (
        <Box flexDirection="column">
          {block.lines.map(line => (
            <Box>
              <Box flexShrink={0}>
                <Text dimColor>{'│ '}</Text>
              </Box>
              <Box flexShrink={1}>
                <Markdown text={line === '' ? ' ' : line} dimColor />
              </Box>
            </Box>
          ))}
        </Box>
      )
    case 'rule':
      return <Text dimColor wrap="truncate-end">{rule}</Text>
    default:
      return <Markdown text={block.text} />
  }
}

// columns is the width the reply is drawn in, which its rules span.
function replyTree($: EngineInterface, e: ResolveInput, text: string, isFirst: boolean, columns: number, isPlain: boolean): RenderElement {
  const { Box, Text } = $.ui.resolve(e)
  const blocks = parseReply(text).filter(block => !isPlain || block.kind !== 'rule')

  return (
    <Box marginTop={1}>
      {isPlain ? null : (
        <Box flexShrink={0} width={3}>
          <Text color={ORANGE}>{isFirst ? '●' : ' '}</Text>
        </Box>
      )}
      <Box flexDirection="column" flexShrink={1} flexGrow={1} gap={1}>
        {blocks.map(block => replyBlock($, e, block, columns - 3, isPlain))}
      </Box>
    </Box>
  )
}

function promptCard($: EngineInterface, e: ResolveInput, text: string): RenderElement {
  const { Box, Text } = $.ui.resolve(e)

  return (
    <Box backgroundColor={PROMPT_CARD} paddingX={2} paddingY={1} marginTop={1} marginBottom={1} gap={2}>
      <Box flexShrink={0}>
        <Text color={ORANGE} bold>❯</Text>
      </Box>
      <Box flexShrink={1}>
        <Text color="text" wrap="wrap">{text}</Text>
      </Box>
    </Box>
  )
}

// A collapsed card keeps its first child, the title row, which carries its summary.
function card(
  $: EngineInterface,
  e: SiteInput,
  color: Color,
  children: RenderElement[],
  gap = 0,
  isCollapsed = false,
): RenderElement {
  const { Box } = $.ui.resolve(e)

  return (
    <Box flexDirection="column" width={e.props.bodyColumns} marginTop={1} gap={gap} borderStyle="round" borderColor={color} paddingX={1}>
      {isCollapsed ? children.slice(0, 1) : children}
    </Box>
  )
}

// Fixed-width parts sit in non-shrinking boxes: Yoga shrinks every flex item in
// proportion to its width, so an unguarded title loses its last letter and wraps.
function cardTitle(
  $: EngineInterface,
  e: SiteInput,
  color: Color,
  title: string,
  subtitle: string | null,
  right?: RenderElement,
): RenderElement {
  const { Box, Text } = $.ui.resolve(e)

  return (
    <Box gap={1}>
      <Box flexShrink={0}>
        <Text color={color} bold>{title}</Text>
      </Box>
      <Box flexGrow={1} flexShrink={1}>
        {subtitle !== null ? <Text color={QUIET} wrap="truncate-end">{`· ${subtitle}`}</Text> : null}
      </Box>
      {right !== undefined ? <Box flexShrink={0}>{right}</Box> : null}
    </Box>
  )
}

// A null percent is a window with no reading: an empty track and no figure.
// Plain, for a screen reader, it is the figure alone.
function meter(
  $: EngineInterface,
  e: SiteInput,
  label: string,
  percent: number | null,
  detail: string,
  isPlain: boolean,
  labelWidth = 3,
  maxWidth = 30,
): RenderElement {
  const { Box, Text } = $.ui.resolve(e)
  const width = Math.min(maxWidth, Math.max(6, e.props.bodyColumns - CARD_CHROME - 19 - labelWidth))
  const filled = percent === null ? 0 : Math.min(width, Math.max(0, Math.round((percent / 100) * width)))
  const color = levelColor(percent ?? 0)

  return (
    <Box gap={1}>
      <Box flexShrink={0} gap={1}>
        <Text color={QUIET}>{label.padEnd(labelWidth)}</Text>
        {isPlain ? null : (
          <Box>
            {filled > 0 ? <Text color={color}>{METER.repeat(filled)}</Text> : null}
            {filled < width ? <Text color={TRACK}>{METER.repeat(width - filled)}</Text> : null}
          </Box>
        )}
        {percent === null ? (
          <Text color={QUIET}>{'—'.padStart(4)}</Text>
        ) : (
          <Text color={color} bold>{`${Math.round(percent)}%`.padStart(4)}</Text>
        )}
      </Box>
      <Box flexShrink={1}>
        <Text color={QUIET} wrap="truncate-end">{detail}</Text>
      </Box>
    </Box>
  )
}

const SECTIONS: ReadonlyArray<[string, Color]> = [
  ['session', ORANGE],
  ['workspace', WORKSPACE_GREEN],
  ['toolkit', TOOLKIT_PURPLE],
  ['agents', AGENTS_BLUE],
]

async function toggleSection($: EngineInterface, key: string): Promise<void> {
  await update($, collapsed, list => (list.includes(key) ? list.filter(one => one !== key) : [...list, key]))
}

// The square is part of the control, and its name says whether it is folded.
function legend($: EngineInterface, e: SiteInput, folded: readonly string[]): RenderElement {
  const { Box, Button, Text } = $.ui.resolve(e)

  return (
    <Box gap={2} marginTop={1} paddingLeft={1}>
      {SECTIONS.map(([key, color]) => (
        <Box key={`legend-box:${key}`}>
          <Button
            key={`legend:${key}`}
            label={`${key}, ${folded.includes(key) ? 'folded' : 'open'}`}
            plain
            hover={{ inverse: false }}
            onPress={() => toggleSection($, key)}
          >
            <Text color={color}>{folded.includes(key) ? '□' : '■'}</Text>
            <Text color={QUIET} hover={{ color: 'text', bold: true }}>{` ${key}`}</Text>
          </Button>
        </Box>
      ))}
    </Box>
  )
}

// Plain, for a screen reader, it leaves Clawd out: block glyphs read as noise.
function headerCard(
  $: EngineInterface,
  e: SiteInput,
  hud: HudInfo | null,
  effortLevel: string | null,
  isPlain: boolean,
): RenderElement {
  const { Box, Text } = $.ui.resolve(e)
  const model = hud === null || hud.model === '' ? 'Claude' : modelLabel(hud.model)
  const level = effortLevel ?? hud?.effortSetting ?? null

  return (
    <Box flexDirection="column" width={e.props.bodyColumns} borderStyle="round" borderColor={ORANGE} paddingX={1}>
      <Box gap={2}>
        {isPlain ? null : (
          <Box flexDirection="column" flexShrink={0}>
            {MASCOT.map(row => (
              <Box>
                {row.map(part =>
                  part.isEye ? (
                    <Text color={MASCOT_BODY} backgroundColor={MASCOT_EYES}>{part.glyphs}</Text>
                  ) : (
                    <Text color={MASCOT_BODY}>{part.glyphs}</Text>
                  ),
                )}
              </Box>
            ))}
          </Box>
        )}
        <Box flexDirection="column" flexShrink={1}>
          <Box gap={1}>
            <Box flexShrink={0}>
              <Text bold>Claude Code</Text>
            </Box>
            {hud !== null && hud.version !== '' ? (
              <Box flexShrink={1}>
                <Text color={QUIET} wrap="truncate-end">v{hud.version}</Text>
              </Box>
            ) : null}
          </Box>
          <Text color={ORANGE} bold wrap="truncate-end">{model}</Text>
          {level !== null ? <Text color={QUIET} wrap="truncate-end">effort {level}</Text> : null}
          <Text color={QUIET} wrap="truncate-end">{hud === null ? '' : cwdLabel(hud)}</Text>
        </Box>
      </Box>
      {hud !== null && (hud.sessionTitle !== null || hud.caveman !== null) ? (
        <Box justifyContent="space-between" marginTop={1} gap={1}>
          <Box flexShrink={1}>
            <Text bold wrap="truncate-end">{hud.sessionTitle ?? ''}</Text>
          </Box>
          {hud.caveman !== null ? (
            <Box flexShrink={0}>
              <Text color={ORANGE}>{hud.caveman}</Text>
            </Box>
          ) : null}
        </Box>
      ) : null}
    </Box>
  )
}

function sessionCard(
  $: EngineInterface,
  e: SiteInput,
  hud: HudInfo | null,
  isWorking: boolean,
  isCollapsed: boolean,
  isPlain: boolean,
): RenderElement {
  const { Text } = $.ui.resolve(e)
  const context = hud?.contextPercent ?? null
  const summary = [
    hud?.costUsd != null ? `$${hud.costUsd.toFixed(2)}` : null,
    hud?.prompts != null ? `${hud.prompts} prompt${hud.prompts === 1 ? '' : 's'}` : null,
    hud?.sessionStartedAt != null ? span(hud.fetchedAt - hud.sessionStartedAt) : null,
  ].filter(part => part !== null)
  const state = isWorking ? <Text color={ORANGE} bold>● working</Text> : <Text color={QUIET}>○ idle</Text>

  return card($, e, ORANGE, [
    cardTitle($, e, ORANGE, 'SESSION', summary.length > 0 ? summary.join(' · ') : null, state),
    context !== null && hud !== null
      ? meter($, e, 'ctx', context, hud.contextTokens !== null && hud.contextWindow > 0 ? `${tokens(hud.contextTokens)}/${tokens(hud.contextWindow)}` : '', isPlain)
      : <Text color={QUIET}>ctx —</Text>,
    // A window's figure comes from this session's last response, so once its
    // reset has passed the figure is the old window's and is not drawn.
    ...(hud?.rateLimits ?? []).map(limit =>
      limit.resetsAt === null || hud === null
        ? meter($, e, limit.label, limit.percent, '', isPlain)
        : limit.resetsAt <= hud.fetchedAt
          ? meter($, e, limit.label, null, 'reset', isPlain)
          : meter($, e, limit.label, limit.percent, `${isPlain ? 'resets in' : '↻'} ${span(limit.resetsAt - hud.fetchedAt)}`, isPlain),
    ),
  ], 1, isCollapsed)
}

function workspaceRow(
  $: EngineInterface,
  e: SiteInput,
  icon: RenderElement,
  body: RenderElement,
  right?: RenderElement,
): RenderElement {
  const { Box } = $.ui.resolve(e)

  return (
    <Box gap={1}>
      <Box flexShrink={0}>{icon}</Box>
      <Box flexGrow={1} flexShrink={1}>{body}</Box>
      {right !== undefined ? <Box flexShrink={0}>{right}</Box> : null}
    </Box>
  )
}

function syncMark($: EngineInterface, e: SiteInput, git: GitState): RenderElement {
  const { Box, Text } = $.ui.resolve(e)
  if (git.upstream === null) return <Text color={QUIET}>local</Text>
  if (git.ahead === null || git.behind === null) return <Text color="warning">upstream gone</Text>
  if (git.ahead === 0 && git.behind === 0) return <Text color={QUIET}>✓ synced</Text>

  return (
    <Box gap={1}>
      {git.ahead > 0 ? <Text color={QUIET}>{`↑${git.ahead}`}</Text> : null}
      {git.behind > 0 ? <Text color={QUIET}>{`↓${git.behind}`}</Text> : null}
      <Text color={QUIET}>{git.upstream.split('/')[0] ?? git.upstream}</Text>
    </Box>
  )
}

function gitRows($: EngineInterface, e: SiteInput, git: GitState, fetchedAt: number): RenderElement[] {
  const { Box, Text } = $.ui.resolve(e)
  const rows: RenderElement[] = []
  const stash = git.stashes > 0 ? <Text color={QUIET}>{`≡ ${git.stashes} stash${git.stashes === 1 ? '' : 'es'}`}</Text> : undefined

  if (git.operation !== null || git.conflicts > 0) {
    rows.push(
      workspaceRow(
        $,
        e,
        <Text color="warning" bold>⚠</Text>,
        <Box gap={1}>
          {git.operation !== null ? (
            <Text color="warning" bold>{`${git.operation.toUpperCase()}${git.step === null ? '' : ` ${git.step}`}`}</Text>
          ) : null}
          {git.conflicts > 0 ? (
            <Text color="error" bold>{`${git.conflicts} conflict${git.conflicts === 1 ? '' : 's'}`}</Text>
          ) : null}
        </Box>,
      ),
    )
  }
  rows.push(
    workspaceRow(
      $,
      e,
      <Text color={WORKSPACE_GREEN}>⎇</Text>,
      git.isDetached ? (
        <Text color={QUIET} bold wrap="truncate-end">{`detached @ ${git.oid?.slice(0, 7) ?? '—'}`}</Text>
      ) : (
        <Text color={QUIET} bold wrap="truncate-end">{git.branch}</Text>
      ),
      syncMark($, e, git),
    ),
  )
  const isClean = git.staged + git.modified + git.untracked + git.conflicts === 0
  rows.push(
    isClean
      ? workspaceRow($, e, <Text color={WORKSPACE_GREEN}>✓</Text>, <Text color={QUIET}>clean</Text>, stash)
      : workspaceRow(
          $,
          e,
          <Text color={WORKSPACE_GREEN}>±</Text>,
          <Box gap={2}>
            {git.staged > 0 ? <Text color={QUIET}>{`✚ ${git.staged} staged`}</Text> : null}
            {git.modified > 0 ? <Text color={QUIET}>{`● ${git.modified} modified`}</Text> : null}
            {git.untracked > 0 ? <Text color={QUIET}>{`? ${git.untracked} new`}</Text> : null}
          </Box>,
          stash,
        ),
  )
  if (git.lastCommit !== null) {
    rows.push(
      workspaceRow(
        $,
        e,
        <Text color={WORKSPACE_GREEN}>◷</Text>,
        <Box gap={1}>
          <Box flexShrink={0}>
            <Text color={QUIET}>{git.lastCommit.hash}</Text>
          </Box>
          <Box flexShrink={1}>
            <Text color={QUIET} wrap="truncate-end">{git.lastCommit.subject}</Text>
          </Box>
        </Box>,
        <Text color={QUIET}>{ago(fetchedAt - git.lastCommit.at)}</Text>,
      ),
    )
  }

  return rows
}

function workspaceCard($: EngineInterface, e: SiteInput, hud: HudInfo | null, isCollapsed: boolean): RenderElement {
  const { Box, Text } = $.ui.resolve(e)
  const git = hud?.git ?? null
  const kube = hud?.kube ?? null
  const where = git !== null ? (git.subdir === null ? git.repo : `${git.repo} › ${git.subdir}`) : hud === null ? null : cwdLabel(hud)
  const rows: RenderElement[] = [
    cardTitle($, e, WORKSPACE_GREEN, 'WORKSPACE', where, git?.isWorktree === true ? <Text color={QUIET}>⧉ worktree</Text> : undefined),
  ]
  if (git !== null && hud !== null) rows.push(...gitRows($, e, git, hud.fetchedAt))
  if (kube !== null) {
    rows.push(
      workspaceRow(
        $,
        e,
        <Text color={KUBE_BLUE} bold>⎈</Text>,
        <Box gap={1}>
          <Box flexShrink={1}>
            {kube.context.startsWith('kind-') ? (
              <Text color={QUIET} wrap="truncate-end">{kube.context}</Text>
            ) : (
              // Bold besides red: a cluster that is not a local kind one must
              // stand out without telling colours apart.
              <Text color="error" bold wrap="truncate-end">{kube.context}</Text>
            )}
          </Box>
          <Box flexShrink={0} gap={1}>
            <Text dimColor>·</Text>
            <Text color={QUIET}>{kube.namespace ?? 'default'}</Text>
          </Box>
        </Box>,
      ),
    )
  }
  if (rows.length === 1) rows.push(<Text color={QUIET}>—</Text>)

  return card($, e, WORKSPACE_GREEN, rows, 1, isCollapsed)
}

function toolkitCard($: EngineInterface, e: SiteInput, groups: readonly ToolkitGroup[], isCollapsed: boolean): RenderElement {
  const { Box, Text } = $.ui.resolve(e)
  const agentCount = groups.reduce((total, group) => total + group.agents.length, 0)
  const skillCount = groups.reduce((total, group) => total + group.skills.length, 0)
  const names = groups.flatMap(group => [...group.agents.map(one => one.name), ...group.skills.map(one => `/${one.name}`)])
  const inner = e.props.bodyColumns - CARD_CHROME
  const nameWidth = Math.min(Math.max(8, ...names.map(name => name.length)), Math.floor(inner * 0.45))
  const row = (key: string, icon: string, name: string, description: string, onPress: () => Promise<void>) => (
    <Box gap={1}>
      <Box flexShrink={0} width={nameWidth + 2} gap={1}>
        <Text color={TOOLKIT_PURPLE}>{icon}</Text>
        <Box key={`${key}-name`}>{quietButton($, e, key, clip(name, nameWidth), onPress)}</Box>
      </Box>
      <Box flexShrink={1}>
        <Text color={QUIET} wrap="truncate-end">{description}</Text>
      </Box>
    </Box>
  )
  const counts = [`${agentCount} agent${agentCount === 1 ? '' : 's'}`, `${skillCount} skill${skillCount === 1 ? '' : 's'}`]

  return card($, e, TOOLKIT_PURPLE, [
    cardTitle($, e, TOOLKIT_PURPLE, 'TOOLKIT', counts.join(' · ')),
    ...(groups.length === 0 ? [<Text color={QUIET}>no agents or skills in .claude/</Text>] : []),
    ...groups.map(group => (
      <Box flexDirection="column" marginTop={1}>
        <Text color={TOOLKIT_PURPLE}>{group.origin === 'repo' ? `repo · ${group.label}` : 'you · ~/.claude'}</Text>
        {group.agents.map(one =>
          row(`toolkit-agent:${group.origin}:${one.name}`, '◆', one.name, one.description, () => askForAgent($, one.name)),
        )}
        {group.skills.map(one =>
          row(`toolkit-skill:${group.origin}:${one.name}`, '/', one.name, one.description, () => runSkill($, one.name)),
        )}
      </Box>
    )),
  ], 0, isCollapsed)
}

// A state other than running or completed is named, not left to its glyph.
function agentDetails(row: AgentRow, isTyped = true): string {
  return [
    row.status === 'running' || row.status === 'completed' ? null : row.status,
    isTyped ? row.type : null,
    modelLabel(row.model),
    `${row.tools} tool${row.tools === 1 ? '' : 's'}`,
    isLive(row) ? row.lastTool : row.tokens !== null ? `${tokens(row.tokens)} tok` : null,
    row.isBackground ? 'bg' : null,
  ]
    .filter(part => part !== null)
    .join(' · ')
}

export function stopwatch(ms: number): string {
  const seconds = Math.max(0, Math.round(ms / 1_000))
  const pad = (value: number) => String(value).padStart(2, '0')
  const hours = Math.floor(seconds / 3_600)
  const minutes = Math.floor((seconds % 3_600) / 60)
  return hours > 0 ? `${hours}:${pad(minutes)}:${pad(seconds % 60)}` : `${minutes}:${pad(seconds % 60)}`
}

function agentsSection(
  $: EngineInterface,
  e: SiteInput,
  rows: readonly AgentRow[],
  at: number,
  viewed: string | undefined,
  isCollapsed: boolean,
  mode: AccessMode,
): RenderElement {
  const { Box, Text } = $.ui.resolve(e)
  const hasViewed = rows.some(row => row.id === viewed)
  const live = rows.filter(isLive)
  const done = rows.filter(row => !isLive(row))
  const counts = [live.length > 0 ? `${live.length} running` : null, done.length > 0 ? `${done.length} done` : null]
    .filter(part => part !== null)
  const clear =
    done.length > 0 ? (
      <Box key="clear-chip" backgroundColor={PROMPT_CARD} paddingX={1}>
        {quietButton($, e, 'clear', '✕ clear', () => update($, agents, list => list.filter(isLive)), 'text')}
      </Box>
    ) : undefined
  const tookOf = (row: AgentRow) => (row.endedAt ?? Math.max(at, row.startedAt)) - row.startedAt
  const longest = Math.max(1, ...rows.map(tookOf))
  const lead = (hasViewed ? 2 : 0) + 2
  const inner = e.props.bodyColumns - CARD_CHROME
  const nameWidth = Math.max(8, Math.floor((inner - lead) * 0.45))
  const barWidth = Math.max(4, inner - lead - nameWidth - 1 - 7 - 1)

  return card(
    $,
    e,
    AGENTS_BLUE,
    [
      cardTitle($, e, AGENTS_BLUE, 'AGENTS', counts.length > 0 ? counts.join(' · ') : null, clear),
      ...(rows.length === 0 ? [<Text color={QUIET}>no agents yet</Text>] : []),
      ...[...live, ...done].map(row => {
        const isRowLive = isLive(row)
        const number = `${rows.indexOf(row) + 1}:`
        const took = tookOf(row)
        const length = Math.max(1, Math.round((took / longest) * barWidth))
        const color = statusColor(row.status)

        // A Button does not truncate its label, so it is cut to the name column.
        return (
          <Box flexDirection="column">
            <Box gap={1}>
              {hasViewed ? (
                <Box flexShrink={0}>
                  <Text color={ORANGE} bold>{row.id === viewed ? '▶' : ' '}</Text>
                </Box>
              ) : null}
              <Box flexShrink={0}>
                <Text color={color}>{statusIcon(row, at, mode.isScreenReader || mode.isReducedMotion)}</Text>
              </Box>
              <Box flexShrink={0} width={nameWidth} gap={1}>
                <Text color={QUIET}>{number}</Text>
                <Box key={`agent-name:${row.id}`} flexShrink={1}>
                  {quietButton(
                    $,
                    e,
                    `agent:${row.id}`,
                    clip(row.description || row.type, Math.max(4, nameWidth - number.length - 1)),
                    () => showAgent($, row.id),
                    isRowLive ? 'text' : QUIET,
                  )}
                </Box>
              </Box>
              <Box flexGrow={1} flexShrink={1}>
                {mode.isScreenReader ? null : (
                  <Text color={isRowLive ? color : TRACK}>{METER.repeat(Math.min(length, barWidth))}</Text>
                )}
              </Box>
              <Box flexShrink={0}>
                <Text color={isRowLive ? AGENTS_BLUE : 'inactive'}>{stopwatch(took).padStart(7)}</Text>
              </Box>
            </Box>
            <Box paddingLeft={lead}>
              <Text color={QUIET} wrap="truncate-end">{agentDetails(row)}</Text>
            </Box>
          </Box>
        )
      }),
    ],
    1,
    isCollapsed,
  )
}

function outcomeMark(outcome: AgentToolOutcome): { glyph: string; color: Color } {
  switch (outcome) {
    case 'ok':
      return { glyph: '✓', color: 'success' }
    case 'error':
      return { glyph: '✗', color: 'error' }
    default:
      return { glyph: '◌', color: ORANGE }
  }
}

function agentViewer(
  $: EngineInterface,
  e: RenderInput<'Pane'>,
  agentId: string,
  row: AgentRow | undefined,
  log: AgentLogView | null,
  at: number,
  mode: AccessMode,
): RenderElement {
  const { Box, Text } = $.ui.resolve(e)
  const isStill = mode.isScreenReader || mode.isReducedMotion
  const entries = log?.agentId === agentId ? log.entries : []
  const took = row === undefined ? null : elapsed((row.endedAt ?? Math.max(at, row.startedAt)) - row.startedAt)
  const time = took === null ? undefined : <Text color={row !== undefined && isLive(row) ? AGENTS_BLUE : 'inactive'}>{took}</Text>

  return (
    <Box flexDirection="column" width={e.props.bodyColumns}>
      <Box key="back-link">{quietButton($, e, 'back', '← HUD', () => showAgent($, null))}</Box>
      {card($, e, AGENTS_BLUE, [
        cardTitle($, e, AGENTS_BLUE, 'AGENT', row === undefined ? null : row.type, time),
        ...(row === undefined
          ? []
          : [
              <Box gap={1}>
                <Box flexShrink={0}>
                  <Text color={statusColor(row.status)}>{statusIcon(row, at, isStill)}</Text>
                </Box>
                <Box flexShrink={1}>
                  <Text bold wrap="truncate-end">{row.description || row.type}</Text>
                </Box>
              </Box>,
              <Text color={QUIET} wrap="truncate-end">{`  ${agentDetails(row, false)}`}</Text>,
            ]),
      ])}
      {log?.isDenied === true ? (
        <Box marginTop={1}>
          <Text color="warning" wrap="wrap">Can't read this agent's transcript.</Text>
        </Box>
      ) : null}
      {log !== null && !log.isDenied && entries.length === 0 ? (
        <Box marginTop={1}>
          <Text color={QUIET}>no messages yet</Text>
        </Box>
      ) : null}
      {entries.map(entry => {
        if (entry.kind === 'prompt') return promptCard($, e, entry.text)
        if (entry.kind === 'reply') return replyTree($, e, entry.text, true, e.props.bodyColumns, mode.isScreenReader)
        const mark = outcomeMark(entry.outcome)
        return (
          <Box gap={1} paddingLeft={3}>
            <Box flexShrink={0} gap={1}>
              <Text color={mark.color}>{mark.glyph}</Text>
              <Text bold>{entry.name}</Text>
            </Box>
            <Box flexShrink={1}>
              <Text color={QUIET} wrap="truncate-end">{entry.summary}</Text>
            </Box>
          </Box>
        )
      })}
    </Box>
  )
}

function compactCard(
  $: EngineInterface,
  e: SiteInput,
  hud: HudInfo | null,
  hintText: string,
  isPlain: boolean,
): RenderElement {
  const { Box, Text } = $.ui.resolve(e)
  const context = hud?.contextPercent ?? null
  const model = hud === null || hud.model === '' ? 'Claude' : modelLabel(hud.model)

  return (
    <Box flexDirection="column" width={e.props.bodyColumns} borderStyle="round" borderColor={ORANGE} paddingX={1}>
      <Box gap={1}>
        <Box flexShrink={1}>
          <Text color={ORANGE} bold wrap="truncate-end">{isPlain ? model : `◆ ${model}`}</Text>
        </Box>
        {hud?.caveman ? (
          <Box flexShrink={1}>
            <Text color={ORANGE} wrap="truncate-start">{hud.caveman}</Text>
          </Box>
        ) : null}
      </Box>
      {hud !== null && hud.cwd !== '' ? (
        <Box justifyContent="space-between" gap={1}>
          <Box flexShrink={1}>
            <Text color={QUIET} wrap="truncate-end">{cwdLabel(hud)}</Text>
          </Box>
          {hud.git !== null ? (
            <Box flexShrink={0}>
              <Text color={ORANGE}>{`${isPlain ? 'branch' : '⎇'} ${hud.git.branch}`}</Text>
            </Box>
          ) : null}
        </Box>
      ) : null}
      <Box justifyContent="space-between" gap={1}>
        {context !== null ? meter($, e, 'context', context, '', isPlain, 7, 24) : <Text color={QUIET}>context —</Text>}
        {hud?.costUsd != null ? (
          <Box flexShrink={0}>
            <Text color={ORANGE}>${hud.costUsd.toFixed(2)}</Text>
          </Box>
        ) : null}
      </Box>
      <Text color={QUIET} wrap="truncate-end">{hintText}</Text>
    </Box>
  )
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'hud',
      description: 'Open the orange-hud side pane: session status and running agents',
    })
    await $.command.register({
      name: 'thoughts',
      description: "Expand or fold every turn's grouped work (intermediate text and tool calls)",
    })
    void refreshLive($)
    $.clock.every(LIVE_MS, () => void refreshLive($))
    void refreshWorkspace($)
    $.clock.every(WORKSPACE_MS, () => void refreshWorkspace($))
    void refreshToolkit($)
    $.clock.every(TOOLKIT_MS, () => void refreshToolkit($))
    if ((await read($, agents)).some(isLive)) ensurePoller($)
    if ((await read($, viewing)) !== null) void refreshAgentLog($)

    return next(e)
  })

  on('command.run', { command: 'hud' }, async $ => {
    await openPane($, true)

    return { text: 'HUD pane opened.' }
  })

  on('command.run', { command: 'rename' }, async ($, e, next) => {
    const renamed = await next(e)
    await refreshTitle($)

    return renamed
  })

  on('command.run', { command: 'effort' }, async ($, e, next) => {
    const ran = await next(e)
    await refreshLive($)

    return ran
  })

  on('command.run', { command: 'model' }, async ($, e, next) => {
    const ran = await next(e)
    await refreshLive($)

    return ran
  })

  on('command.run', { command: 'thoughts' }, async $ => {
    const isShown = !(await read($, showThoughts))
    await update($, showThoughts, () => isShown)

    return { text: isShown ? 'Turn work expanded.' : 'Turn work folded.' }
  })

  on('ui.close', { id: PANE }, async ($, e, next) => {
    // The frame's close mark cannot be hidden, so the person's close is refused:
    // answering without next keeps the pane open.
    if (e.origin.kind === 'person') return { value: undefined }
    const closed = await next(e)
    $.ui.invalidate('ui.render')

    return closed
  })

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    void refreshLive($)
    void refreshWorkspace($)
    // A turn can have written an agent or skill definition.
    if (e.agentId === undefined) void refreshToolkit($)
    if (e.agentId !== undefined && e.agentId === (await read($, viewing))) void refreshAgentLog($)
    const group = tracker.group
    if (e.agentId === undefined && group !== null && group.isActive) {
      const settled: TurnGroupView = { ...group, isActive: false }
      tracker.group = settled
      void update($, memberOf(turnGroup, { requestId: settled.head }), () => settled)
    }

    return done
  })

  on('classic.UserPromptSubmit', ($, e, next) => {
    noteSession($, e)

    return next(e)
  })

  on('classic.PostToolUse', ($, e, next) => {
    noteSession($, e)

    return next(e)
  })

  on('classic.Stop', ($, e, next) => {
    noteSession($, e)

    return next(e)
  })

  on('classic.SessionStart', ($, e, next) => {
    noteSession($, e)

    return next(e)
  })

  on('classic.PostToolUseFailure', ($, e, next) => {
    noteSession($, e)

    return next(e)
  })

  on('classic.Notification', ($, e, next) => {
    noteSession($, e)

    return next(e)
  })

  on('session.append', async ($, e, next) => {
    const stored = await next(e)
    if (stored.deny !== undefined || e.agentId !== undefined) return stored
    if (e.door !== 'prompt' && e.message.type === 'user') {
      const level = effortSet(e.message.content.map(block => (block.type === 'text' ? block.text : '')).join('\n'))
      if (level !== null) await storeEffort($, level)
    }

    const change = noteGroupRow(tracker, {
      uuid: stored.uuid,
      isPrompt: e.message.type === 'user' && e.door === 'prompt',
      isAssistant: e.message.type === 'assistant',
      blocks: e.message.content,
    })
    if (change !== null) {
      await update($, memberOf(turnGroup, { requestId: change.view.head }), () => change.view)
      for (const key of change.members) void update($, memberOf(groupOf, { requestId: key }), () => change.view.head)
    }

    return stored
  })

  // Under a screen reader the engine's own drawing of a message, made for one, stays.
  on('ui.render', { component: 'AssistantMessage' }, ($, e, next) =>
    drawGrouped($, e, [e.requestId], async () =>
      e.props.isSummary === true || e.props.text.trim() === '' || /^API Error/.test(e.props.text) || (await read($, access)).isScreenReader
        ? next(e)
        : replyTree($, e, e.props.text, e.props.isFirstOfReply, e.viewport?.columns ?? 80, false),
    ),
  )

  on('ui.render', { component: 'ToolUse' }, ($, e, next) => drawGrouped($, e, [e.props.tool_use_id], () => next(e)))

  on('ui.render', { component: 'ToolResult' }, ($, e, next) => drawGrouped($, e, [e.props.tool_use_id], () => next(e), false))

  on('ui.render', { component: 'ToolProgress' }, ($, e, next) => drawGrouped($, e, [e.props.tool_use_id], () => next(e), false))

  on('ui.render', { component: 'ToolGroup' }, ($, e, next) =>
    drawGrouped(
      $,
      e,
      e.props.calls.flatMap(call => (call.tool_use_id === undefined ? [] : [call.tool_use_id])),
      () => next(e),
    ),
  )

  on('ui.render', { component: 'UserMessage', props: { origin: { kind: 'composer' } } }, async ($, e, next) =>
    (await read($, access)).isScreenReader ? next(e) : promptCard($, e, e.props.text),
  )

  on('agent.spawn', async ($, e, next) => {
    const spawned = await next(e)
    if (spawned.deny !== undefined || spawned.agentId === undefined || e.workflow !== undefined) {
      return spawned
    }

    const startedAt = await $.clock.now()
    const row: AgentRow = {
      id: spawned.agentId,
      toolUseId: e.tool_use_id,
      description: printable(e.description),
      type: printable(e.subagentType),
      model: spawned.model,
      isBackground: e.background === true,
      status: 'running',
      startedAt,
      endedAt: null,
      tools: 0,
      lastTool: null,
      tokens: null,
    }
    await update($, agents, list => [...list.filter(one => one.id !== row.id), row].slice(-MAX_AGENTS))
    await update($, now, () => startedAt)
    ensurePoller($)
    if (isFullscreen !== false) void openPane($, false)

    return spawned
  })

  on('tool.call', { tool: 'Agent' }, async ($, e, next) => {
    const ran = await next(e)
    const toolUseId = e.tool_use_id
    if (toolUseId === undefined) return ran

    const result = ran.result as { status?: string; totalToolUseCount?: number; totalTokens?: number } | undefined
    if (ran.deny !== undefined || ran.isError === true) {
      await finish($, row => row.toolUseId === toolUseId, 'failed')
    } else if (result?.status === 'completed') {
      await finish($, row => row.toolUseId === toolUseId, 'completed', {
        tools: result.totalToolUseCount,
        tokens: result.totalTokens,
      })
    }

    return ran
  })

  on('tool.call', ($, e, next) => {
    if (e.agentId !== undefined) void countTool($, e.agentId, e.tool)

    return next(e)
  })

  // The hint is drawn in the HUD instead. A render hook may not write state, so
  // the captured text is handed over from a timer. The engine keeps drawing the
  // permission mode beside this site, where it stays.
  on('ui.render', { component: 'PromptHint' }, ($, e) => {
    const text = e.props.hint
    if (text !== lastHint) {
      lastHint = text
      $.clock.after(1, () => void update($, hint, () => text))
    }
    const { Box } = $.ui.resolve(e)

    return <Box />
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    // The band is where the engine says whether a turn runs; the pane reads it
    // from state, handed over from a timer as the hint is.
    const isWorking = e.props.isWorking
    if (isWorking !== lastWorking) {
      lastWorking = isWorking
      $.clock.after(1, () => void update($, working, () => isWorking))
    }
    if (e.props.hasSurvey) return next(e)

    // Docking unasked only makes sense where the pane becomes a sidebar, which
    // only a render input reveals; the open itself must happen outside the draw.
    if (e.viewport?.isFullscreen !== undefined) isFullscreen = e.viewport.isFullscreen
    if (isFullscreen === true && !isAutoOpened) {
      isAutoOpened = true
      $.clock.after(1, () => void openPane($, false))
    }

    const [hud, hintText, isInPane, mode] = await Promise.all([read($, info), read($, hint), isHudInPane($), read($, access)])
    if (hud === null) queueRefresh($)
    if (!isInPane) return compactCard($, e, hud, hintText, mode.isScreenReader)
    if (hintText === '') return next(e)

    const { Box, Text } = $.ui.resolve(e)

    return (
      <Box width={e.props.bodyColumns} paddingX={1}>
        <Text color={QUIET} wrap="truncate-end">{hintText}</Text>
      </Box>
    )
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box } = $.ui.resolve(e)
    const [hud, rows, at, effortLevel, shown, log, isWorking, tools, folded, mode] = await Promise.all([
      read($, info),
      read($, agents),
      read($, now),
      read($, effort),
      read($, viewing),
      read($, agentLog),
      read($, working),
      read($, toolkit),
      read($, collapsed),
      read($, access),
    ])
    if (hud === null) queueRefresh($)
    // Every part sizes itself from bodyColumns, so each is drawn for the width
    // left beside the gutter that keeps text off the pane's right edge.
    const inner: RenderInput<'Pane'> = {
      ...e,
      props: { ...e.props, bodyColumns: Math.max(1, e.props.bodyColumns - PANE_GUTTER) },
    }

    return (
      <Box width={e.props.bodyColumns} paddingRight={PANE_GUTTER}>
        {shown !== null ? (
          agentViewer($, inner, shown, rows.find(row => row.id === shown), log, at, mode)
        ) : (
          <Box flexDirection="column" width={inner.props.bodyColumns}>
            {headerCard($, inner, hud, effortLevel, mode.isScreenReader)}
            {legend($, inner, folded)}
            {sessionCard($, inner, hud, isWorking, folded.includes('session'), mode.isScreenReader)}
            {workspaceCard($, inner, hud, folded.includes('workspace'))}
            {toolkitCard($, inner, tools, folded.includes('toolkit'))}
            {agentsSection($, inner, rows, at, e.props.view.agentId, folded.includes('agents'), mode)}
          </Box>
        )}
      </Box>
    )
  })
}

